mapper.select:
select count(1) as value ,COALESCE(type,'其它') as type,COALESCE(type,'其它') as name
from todo_item
where 1=1

    and user_id = #{userId}


    and create_time >= #{startTime}


    and create_time <= #{endTime}


    and modular = #{modular}


    and state = #{state}

GROUP by type

select count(1) as value,COALESCE(type,'其它') as type,state as name
from todo_item
where 1=1

    and user_id = #{userId}


    and create_time >= #{startTime}


    and create_time <= #{endTime}


    and modular = #{modular}

GROUP by type,state

select count(1) as value,COALESCE(d.dept_name,'其它') as name,i.dept_id
from todo_item i
LEFT JOIN sys_dept d on d.dept_id = i.dept_id
where 1=1

    and i.dept_id = #{deptId}


    and i.create_time >= #{startTime}


    and i.create_time <= #{endTime}


    and i.state = #{state}


    and i.type = #{type}

group by i.dept_id,d.dept_name

select count(1) as value,COALESCE(d.dept_name,'其它') as name,COALESCE(i.type,'其它') as type,i.dept_id as code
from todo_item i LEFT JOIN sys_dept d
on d.dept_id = i.dept_id
where 1=1

    and i.dept_id = #{deptId}


    and i.create_time >= #{startTime}


    and i.create_time <= #{endTime}


    and i.state = #{state}

group by i.dept_id, i.type,d.dept_name

select count(1) as value,state as code
from todo_item
where 1=1

    and user_id = #{userId}


    and create_time >= #{startTime}


    and create_time <= #{endTime}


    and type = #{type}

GROUP by state

select count(1) as value ,year,month
from todo_item
where 1=1

    and user_id = #{userId}


    and dept_id = #{deptId}


    and create_time >= #{startTime}


    and create_time <= #{endTime}


    and type = #{type}


    and state = #{state}

GROUP BY year,month

select count(1) as value ,year,month,COALESCE(modular,'其它') as type
from todo_item
where 1=1

    and user_id = #{userId}


    and dept_id = #{deptId}


    and create_time >= #{startTime}


    and create_time <= #{endTime}


    and state = #{state}

GROUP BY year,month,modular

select count(1) as value,COALESCE(d.dept_name,'其它') as dept_name ,i.user_id as code, COALESCE(i.type,'其它') as type,u.nick_name as name
from todo_item i
left join sys_user u on i.user_id = u.user_id
LEFT JOIN sys_dept d on d.dept_id = i.dept_id
where 1=1

    and i.dept_id = #{deptId}


    and i.user_id = #{userId}


    and i.create_time >= #{startTime}


    and i.create_time <= #{endTime}


    and i.type = #{type}


    and i.state = #{state}

group by i.dept_id, d.dept_name,i.user_id,i.type,u.nick_name

SELECT item.business_code, item.title, item.type , item.state , item.user_id, u.nick_name , d.dept_name , item.submit_time, item.modular, item.callback_link FROM todo_item item LEFT JOIN sys_user u ON item.user_id = u.user_id LEFT JOIN sys_dept d ON item.dept_id = d.dept_id WHERE 1 =1
and item.business_code like concat('%',#{businessCode},'%')
and item.title like concat('%',#{title},'%')
and item.state = #{state}
and item.user_id = #{userId}
and item.submit_time >= #{params.beginTime}
and item.submit_time <= #{params.endTime}
and item.dept_id = #{deptId}
and item.modular = #{modular}

SELECT ${sql}
u.nick_name as 名称, COUNT(user_name) as 总数
u.nick_name as name, COUNT(user_name) as count
from todo_item item LEFT JOIN sys_user u ON item.user_id = u.user_id WHERE 1=1
and item.user_id in (#{userId})
and item.dept_id in (#{deptId})
and item.modular in (#{type})
and item.submit_time >= #{startTime}
and item.submit_time <= #{endTime}
GROUP BY u.user_name,u.nick_name

SELECT ${sql}
d.dept_name as 名称, count(dept_name) as 总数
d.dept_name AS name, count(dept_name) AS count
FROM todo_item item LEFT JOIN sys_dept d ON item.dept_id = d.dept_id WHERE 1=1
and item.dept_id in (#{deptId})
and item.type in (#{type})
and item.submit_time >= #{startTime}
and item.submit_time <= #{endTime}
GROUP BY d.dept_name
